        icon: () => icon?.() ?? <Clock className="size-3" />,
        appearance,
        label: label ?? 'TP Review',
      },
      tp_approved: {
        variant: 'success' as const,
        icon: () => icon?.() ?? <CheckCircle className="size-3" />,
        appearance,
        label: label ?? 'TP Approved',
      },
      tp_rejected: {
        variant: 'destructive' as const,
        icon: () => icon?.() ?? <XCircle className="size-3" />,
        appearance,
        label: label ?? 'TP Rejected',
      },
      tp_removed: {
        variant: 'primary' as const,
        icon: () => icon?.() ?? <Ban className="size-3" />,
        appearance,
        label: label ?? 'TP Removed',
      },
      mkt_review: {
        variant: 'warning' as const,
        icon: () => icon?.() ?? <Clock className="size-3" />,
        appearance,
        label: label ?? 'MKT Review',
      },
      mkt_approved: {
        variant: 'success' as const,
        icon: () => icon?.() ?? <CheckCircle className="size-3" />,
        appearance,
        label: label ?? 'MKT Approved',
      },
      mkt_rejected: {
        variant: 'destructive' as const,
        icon: () => icon?.() ?? <XCircle className="size-3" />,
        appearance,
        label: label ?? 'MKT Rejected',
      },
      mkt_removed: {
        variant: 'primary' as const,
        icon: () => icon?.() ?? <Ban className="size-3" />,
        appearance,
        label: label ?? 'MKT Removed',
      },
      ops_review: {
        variant: 'warning' as const,
        icon: () => icon?.() ?? <Clock className="size-3" />,
        appearance,
        label: label ?? 'Ops Review',
      },
      ops_approved: {
        variant: 'success' as const,
        icon: () => icon?.() ?? <CheckCircle className="size-3" />,
        appearance,
        label: label ?? 'Ops Approved',
      },
      ops_rejected: {
        variant: 'destructive' as const,
        icon: () => icon?.() ?? <XCircle className="size-3" />,
        appearance,
        label: label ?? 'Ops Rejected',
      },
      ops_removed: {
        variant: 'primary' as const,
        icon: () => icon?.() ?? <Ban className="size-3" />,
        appearance,
        label: label ?? 'Ops Removed',
      },
      fin_review: {
        variant: 'warning' as const,
        icon: () => icon?.() ?? <Clock className="size-3" />,
        appearance,
        label: label ?? 'Finance Review',
      },
      fin_approved: {
        variant: 'success' as const,
        icon: () => icon?.() ?? <CheckCircle className="size-3" />,
        appearance,
        label: label ?? 'Finance Approved',
      },
      fin_rejected: {
        variant: 'destructive' as const,
        icon: () => icon?.() ?? <XCircle className="size-3" />,
        appearance,
        label: label ?? 'Finance Rejected',
      },
      ops_fin_approved: {
        variant: 'success' as const,
        icon: () => icon?.() ?? <CheckCircle className="size-3" />,
        appearance,
        label: label ?? 'Ops & Finance Approved',
      },
      ops_fin_rejected: {
        variant: 'destructive' as const,
        icon: () => icon?.() ?? <XCircle className="size-3" />,
        appearance,
        label: label ?? 'Ops/Finance Rejected',
      },
      gd_review: {
        variant: 'warning' as const,
        icon: () => icon?.() ?? <Clock className="size-3" />,
        appearance,
        label: label ?? 'GD Review',
      },
      gd_rejected: {
        variant: 'destructive' as const,
        icon: () => icon?.() ?? <XCircle className="size-3" />,
        appearance,
        label: label ?? 'GD Rejected',
      },

      ['promotion_planning']: {
        variant: 'warning' as const,
        icon: () => icon?.() ?? <TrendingUp className="size-3" />,
        appearance,
        label: label ?? 'Promotion Planning',
      },

      Innovation: {
        variant: 'warning' as const,
        appearance,
        label: label ?? 'Innovation',
      },

      // Empty or null value
      '': {
        variant: 'info' as const,
        icon: () => icon?.() ?? <AlertCircle className="size-3" />,
        appearance,
        label: label ?? 'Empty',
      },
      // Undefined or unknown value
      undefined: {
        variant: 'info' as const,
        icon: () => icon?.() ?? <HelpCircle className="size-3" />,
        appearance,
        label: label ?? 'Unknown',
      },
    };

    // Handle empty, null, or undefined values
    if (!value || value.trim() === '') {
      return (
        variantMap[''] || {
          variant: 'info' as const,
          icon: () => icon?.() ?? <AlertCircle className="size-3" />,
          appearance,
          label: label ?? 'Empty',
        }
      );
    }

    // Return matched value or default for undefined
    return (
      variantMap[value] || {
        variant: 'info' as const,
        icon: () => icon?.() ?? null,
        appearance,
        label: label ?? value,
      }
    );
  };

  return {
    getVariant,
  };
}

import * as React from 'react';

export interface UseControlledStateOptions<T> {
  /**
   * Controlled value. When provided, the component is controlled.
   */
  value?: T;
  /**
   * Default value for uncontrolled mode.
   */
  defaultValue?: T;
  /**
   * Callback fired when the value changes (for controlled mode).
   */
  onChange?: (value: T) => void;
}

/**
 * Hook to manage controlled/uncontrolled state for form controls.
 *
 * @example
 * // Controlled mode
 * const [value, setValue] = useControlledState({
 *   value: controlledValue,
 *   onChange: (newValue) => setControlledValue(newValue),
 * });
 *
 * @example
 * // Uncontrolled mode
 * const [value, setValue] = useControlledState({
 *   defaultValue: 'initial',
 * });
 */
export function useControlledState<T>({
  value: controlledValue,
  defaultValue,
  onChange,
}: UseControlledStateOptions<T>): [T | undefined, (value: T | undefined) => void] {
  // A field is considered controlled **only** when `value` is provided.
  // Presence of `onChange` alone should not force controlled mode; this
  // allows patterns like uncontrolled components that still emit changes.
  const isControlled = controlledValue !== undefined;
  const [internalValue, setInternalValue] = React.useState<T | undefined>(defaultValue);

  const value = isControlled ? controlledValue : internalValue;

  const setValue = (newValue: T | undefined) => {
    if (!isControlled) {
      setInternalValue(newValue);
    }
    // Always notify listeners when the value changes, regardless of mode.
    onChange?.(newValue as T);
  };

  return [value, setValue];
}

import { useRef } from 'react';

/**
 * Creates a debounced version of the provided callback that delays execution until
 * the user stops calling it for the specified delay.
 */
export function useDebounceCallback<T extends (...args: readonly any[]) => void>(
  callback: T,
  delay: number
) {
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  return (...args: Parameters<T>) => {
    if (timeoutRef.current !== null) {
      clearTimeout(timeoutRef.current);
    }

    timeoutRef.current = setTimeout(() => {
      callback(...args);
    }, delay);
  };
}

import * as React from 'react';

export function useDebouncedValue<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = React.useState(value);

  React.useEffect(() => {
    const handle = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handle);
    };
  }, [value, delay]);

  return debouncedValue;
}

import { useEffect, useState, useCallback, useRef } from 'react';

interface UseFullHeightTableOptions {
  /**
   * Offset from the top of the viewport (e.g., header height)
   * If not provided, will auto-detect common header selectors
   * @default auto-detect
   */
  topOffset?: number;

  /**
   * Offset from the bottom of the viewport (e.g., footer height)
   * @default 0
   */
  bottomOffset?: number;

  /**
   * Additional padding to subtract from the calculated height
   * If not provided, will auto-detect elements above the table
   * @default auto-detect
   */
  additionalPadding?: number;

  /**
   * Minimum height for the table
   * @default 300
   */
  minHeight?: number;

  /**
   * Maximum height for the table (optional)
   */
  maxHeight?: number;

  /**
   * CSS selector for elements above the table to calculate their height
   * These elements will be subtracted from the available height
   * @default auto-detect common selectors
   */
  elementsAbove?: string[];

  /**
   * CSS selector for elements below the table to calculate their height
   * These elements will be subtracted from the available height
   */
  elementsBelow?: string[];

  /**
   * Auto-detect common header/navbar elements
   * @default true
   */
  autoDetectHeaders?: boolean;

  /**
   * Auto-detect elements above the table (filters, toolbars, etc.)
   * @default true
   */
  autoDetectElementsAbove?: boolean;

  /**
   * Final adjustment to subtract from calculated height (for fine-tuning)
   * @default 0
   */
  finalAdjustment?: number;
}

interface UseFullHeightTableReturn {
  /**
   * The calculated height for the table
   */
  height: string;

  /**
   * Ref to attach to the table container for more accurate calculations
   */
  containerRef: React.RefObject<HTMLDivElement | null>;

  /**
   * Function to manually recalculate the height
   */
  recalculate: () => void;

  /**
   * The raw calculated height in pixels
   */
  heightPx: number;
}

/**
 * Hook to calculate the full height available for a DataTable
 * Takes into account viewport height, offsets, and elements above/below the table
 * Only calculates once after initial render, never recalculates automatically
 */
export function useFullHeightTable(
  options: UseFullHeightTableOptions = {}
): UseFullHeightTableReturn {
  const { minHeight, finalAdjustment = 0 } = options;

  const [heightPx, setHeightPx] = useState<number>(minHeight || 0);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const hasCalculatedRef = useRef(false);
  const optionsRef = useRef(options);

  // Store initial options to use in calculation
  optionsRef.current = options;

  const calculateHeight = useCallback(() => {
    // Use stored options from initial render
    const opts = optionsRef.current;

    try {
      // Get viewport height
      const viewportHeight = window.innerHeight;

      // Auto-detect common header/navbar selectors
      const defaultHeaderSelectors = [
        'nav',
        'header',
        '[role="banner"]',
        '.navbar',
        '.header',
        '.top-bar',
      ];

      // Auto-detect elements above table (filters, toolbars, etc.)
      const defaultElementsAboveSelectors = [
        '.data-table-container > div:first-child', // First child in data-table-container (usually filters)
        '.filters',
        '.toolbar',
        '.actions',
        '.search-bar',
        '.filter-bar',
      ];

      // Determine which selectors to use
      let selectorsToCheck: string[] = [];

      if (opts.autoDetectHeaders && !opts.topOffset) {
        selectorsToCheck = [...selectorsToCheck, ...defaultHeaderSelectors];
      }

      if (opts.autoDetectElementsAbove && !opts.additionalPadding) {
        selectorsToCheck = [...selectorsToCheck, ...defaultElementsAboveSelectors];
      }

      if (opts.elementsAbove) {
        selectorsToCheck = [...selectorsToCheck, ...opts.elementsAbove];
      }

      // Calculate height of detected elements (avoid double counting)
      let elementsAboveHeight = 0;
      const processedElements = new Set<Element>();

      selectorsToCheck.forEach((selector) => {
        try {
          const elements = document.querySelectorAll(selector);
          elements.forEach((element) => {
            // Skip if we already processed this element or its parent
            if (processedElements.has(element)) return;

            // Check if any parent is already processed
            let hasProcessedParent = false;
            for (const processed of processedElements) {
              if (processed.contains(element) || element.contains(processed)) {
                hasProcessedParent = true;
                break;
              }
            }

            if (!hasProcessedParent) {
              const rect = element.getBoundingClientRect();
              elementsAboveHeight += rect.height;
              processedElements.add(element);
            }
          });
        } catch (_e) {
          // Ignore invalid selectors
        }
      });

      // Calculate height of elements below the table
      let elementsBelowHeight = 0;
      (opts.elementsBelow || []).forEach((selector) => {
        try {
          const elements = document.querySelectorAll(selector);
          elements.forEach((element) => {
            const rect = element.getBoundingClientRect();
            elementsBelowHeight += rect.height;
          });
        } catch (_e) {
          // Ignore invalid selectors
        }
      });

      // Calculate container top position
      let containerTop = 0;
      if (containerRef.current) {
        const containerRect = containerRef.current.getBoundingClientRect();
        containerTop = containerRect.top;
      } else if (opts.topOffset !== undefined) {
        containerTop = opts.topOffset;
      }

      // Calculate available height
      let availableHeight =
        viewportHeight -
        containerTop -
        (opts.bottomOffset || 0) -
        elementsAboveHeight -
        elementsBelowHeight -
        (opts.additionalPadding || 0);

      // Apply min/max constraints
      availableHeight = Math.max(availableHeight || 0, opts.minHeight || 0);
      if (opts.maxHeight) {
        availableHeight = Math.min(availableHeight, opts.maxHeight);
      }
      setHeightPx(Math.floor(availableHeight));
    } catch (error) {
      console.warn('Error calculating table height:', error);
      setHeightPx(opts.minHeight || 0);
    }
  }, []);

  // Stable recalculate function that doesn't change on every render
  const recalculate = useCallback(() => {
    calculateHeight();
  }, [calculateHeight]);

  // Calculate only once after DOM is ready (not on initial render)
  useEffect(() => {
    if (hasCalculatedRef.current) {
      return;
    }

    // Use setTimeout to ensure DOM is fully rendered
    const timeoutId = setTimeout(() => {
      if (!hasCalculatedRef.current) {
        calculateHeight();
        hasCalculatedRef.current = true;
      }
    }, 0);

    return () => {
      clearTimeout(timeoutId);
    };
  }, [calculateHeight]);

  const height = `${(heightPx || 0) - finalAdjustment}px`;
  return {
    height,
    containerRef,
    recalculate,
    heightPx: heightPx || 0,
  };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { useIntersectionObserver } from './use-intersection-observer';

const DEFAULT_THRESHOLD = 0.5;
const DEFAULT_ROOT_MARGIN = '200px';

export interface InfiniteScrollOptions<T> {
  /**
   * Async function to load options
   * @param search - Search query
   * @param page - Page number for pagination (starts at 1)
   * @returns Promise with options and hasMore flag
   */
  loadOptions: (
    search: string,
    page: number
  ) => Promise<{
    options: T[];
    hasMore: boolean;
  }>;

  /**
   * Debounce delay for search in milliseconds
   * @default 300
   */
  debounceMs?: number;

  /**
   * Whether to load initial options when enabled becomes true
   * @default false
   */
  enabled?: boolean;

  /**
   * Initial search value
   * @default ''
   */
  initialSearch?: string;

  /**
   * Root margin used by IntersectionObserver to preload before reaching the bottom.
   * @default '200px'
   */
  observerRootMargin?: string;

  /**
   * Custom intersection root. Set this to a scroll container element when
   * infinite loading should trigger based on container scrolling, not viewport.
   */
  observerRoot?: Element | Document | null;

  /**
   * Optional key extractor used to dedupe merged options when appending pages.
   */
  getOptionKey?: (option: T) => string | number;
}

export interface InfiniteScrollResult<T> {
  /** Current options */
  options: T[];
  /** Current search value */
  search: string;
  /** Function to update search value */
  setSearch: (value: string, options?: { skipFetch?: boolean }) => void;
  /** Current page number */
  page: number;
  /** Whether there are more items to load */
  hasMore: boolean;
  /** Whether initial loading is in progress */
  isLoading: boolean;
  /** Whether loading more items is in progress */
  isLoadingMore: boolean;
  /** Error object from the latest failed request, if any */
  error: unknown;
  /** Ref to attach to the element that triggers infinite scroll */
  observerTarget: React.RefCallback<HTMLDivElement>;
  /** Function to manually fetch options */
  fetchOptions: (searchQuery: string, pageNum: number, append?: boolean) => Promise<void>;
  /** Function to reset all state */
  reset: () => void;
}

/**
 * Custom hook for infinite scroll functionality with debounced search
 * @template T - Type of option items
 */
export function useInfiniteScroll<T>({
  loadOptions,
  debounceMs = 300,
  enabled = false,
  initialSearch = '',
  observerRootMargin = DEFAULT_ROOT_MARGIN,
  observerRoot = null,
  getOptionKey,
}: InfiniteScrollOptions<T>): InfiniteScrollResult<T> {
  const [options, setOptions] = useState<T[]>([]);
  const [search, setSearchState] = useState(initialSearch);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [error, setError] = useState<unknown>(null);

  const debounceTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const requestIdRef = useRef(0);
  const isMountedRef = useRef(true);
  const hasFetchedInitialRef = useRef(false);
  const skipNextSearchFetchRef = useRef(false);
  const wasEnabledRef = useRef(enabled);
  const fetchOptionsRef = useRef<
    (searchQuery: string, pageNum: number, append?: boolean) => Promise<void>
  >(async () => {});
  const latestStateRef = useRef({
    hasMore,
    isLoading,
    isLoadingMore,
    page,
    search,
    optionCount: options.length,
  });

  latestStateRef.current = {
    hasMore,
    isLoading,
    isLoadingMore,
    page,
    search,
    optionCount: options.length,
  };

  const setSearch = useCallback((value: string, options?: { skipFetch?: boolean }) => {
    if (options?.skipFetch) {
      skipNextSearchFetchRef.current = true;
    }
    setSearchState(value);
  }, []);

  const invalidatePendingRequests = useCallback(() => {
    requestIdRef.current += 1;
    if (!isMountedRef.current) return;
    setIsLoading(false);
    setIsLoadingMore(false);
  }, []);

  const { ref: intersectionRef, isIntersecting } = useIntersectionObserver({
    root: observerRoot,
    rootMargin: observerRootMargin,
    threshold: DEFAULT_THRESHOLD,
    enabled,
  });

  const observerTarget = useCallback(
    (node: HTMLDivElement | null) => {
      intersectionRef(node);
    },
    [intersectionRef]
  );

  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
      requestIdRef.current += 1;
      clearTimeout(debounceTimer.current);
    };
  }, []);

  // Load options function
  const fetchOptions = useCallback(
    async (searchQuery: string, pageNum: number, append = false) => {
      const requestId = ++requestIdRef.current;

      try {
        if (pageNum === 1) {
          setIsLoading(true);
        } else {
          setIsLoadingMore(true);
        }
        setError(null);

        const result = await loadOptions(searchQuery, pageNum);
        if (!isMountedRef.current || requestId !== requestIdRef.current) return;

        setOptions((prev) => {
          const nextOptions = append ? [...prev, ...result.options] : result.options;
          if (!append || !getOptionKey) {
            return nextOptions;
          }

          const seen = new Set<string>();
          return nextOptions.filter((option) => {
            const key = String(getOptionKey(option));
            if (seen.has(key)) return false;
            seen.add(key);
            return true;
          });
        });
        setHasMore(result.hasMore);
        setPage(pageNum);
        if (pageNum === 1) {
          hasFetchedInitialRef.current = true;
        }
      } catch (error) {
        if (!isMountedRef.current || requestId !== requestIdRef.current) return;
        setError(error);
        console.error('Error loading options:', error);
      } finally {
        if (isMountedRef.current && requestId === requestIdRef.current) {
          setIsLoading(false);
          setIsLoadingMore(false);
        }
      }
    },
    [loadOptions, getOptionKey]
  );

  useEffect(() => {
    fetchOptionsRef.current = fetchOptions;
  }, [fetchOptions]);

  const tryLoadNextPage = useCallback(() => {
    if (!enabled || !hasFetchedInitialRef.current) return;

    const state = latestStateRef.current;
    if (!state.hasMore || state.isLoading || state.isLoadingMore) return;

    // Guard against duplicate triggers before React applies loading state.
    latestStateRef.current = {
      ...state,
      isLoadingMore: true,
    };
    void fetchOptionsRef.current(state.search, state.page + 1, true);
  }, [enabled]);

  // Debounced search
  useEffect(() => {
    if (!enabled) return;

    const wasEnabled = wasEnabledRef.current;
    wasEnabledRef.current = true;
    const state = latestStateRef.current;

    if (!wasEnabled && state.optionCount > 0 && state.search === initialSearch) {
      return;
    }

    if (skipNextSearchFetchRef.current) {
      skipNextSearchFetchRef.current = false;
      return;
    }

    invalidatePendingRequests();
    clearTimeout(debounceTimer.current);

    // On initial enable, fetch immediately without debounce for instant loading.
    // Debounce only applies to subsequent user-typed search changes.
    if (!wasEnabled) {
      setPage(1);
      setHasMore(true);
      void fetchOptionsRef.current(search, 1, false);
      return;
    }

    debounceTimer.current = setTimeout(() => {
      setPage(1);
      setHasMore(true);
      void fetchOptionsRef.current(search, 1, false);
    }, debounceMs);

    return () => {
      clearTimeout(debounceTimer.current);
    };
  }, [search, debounceMs, enabled, invalidatePendingRequests, initialSearch]);

  useEffect(() => {
    if (!enabled) {
      wasEnabledRef.current = false;
      hasFetchedInitialRef.current = false;
    }
  }, [enabled]);

  // Trigger next page load when sentinel is intersecting.
  // Including `isLoadingMore` ensures we re-evaluate after a page finishes
  // loading in case the sentinel is still visible.
  useEffect(() => {
    if (!enabled || !isIntersecting || !hasFetchedInitialRef.current) return;
    tryLoadNextPage();
  }, [enabled, isIntersecting, isLoadingMore, tryLoadNextPage]);

  // Reset function
  const reset = useCallback(() => {
    clearTimeout(debounceTimer.current);
    invalidatePendingRequests();
    hasFetchedInitialRef.current = false;
    setOptions([]);
    setSearch(initialSearch);
    setPage(1);
    setHasMore(true);
    setIsLoading(false);
    setIsLoadingMore(false);
    setError(null);
  }, [initialSearch, invalidatePendingRequests]);

  return {
    options,
    search,
    setSearch,
    page,
    hasMore,
    isLoading,
    isLoadingMore,
    error,
    observerTarget,
    fetchOptions,
    reset,
  };
}

import React from 'react';

export type UseIntersectionObserverOptions = {
  threshold?: number | number[];
  root?: Element | Document | null;
  rootMargin?: string;
  /** Stop observing once the element becomes visible */
  freezeOnceVisible?: boolean;
  /** Callback fired on every intersection change */
  onChange?: (entry: IntersectionObserverEntry) => void;
  /** Conditionally enable/disable the observer */
  enabled?: boolean;
};

export type UseIntersectionObserverReturn = {
  ref: (node: Element | null) => void;
  entry: IntersectionObserverEntry | undefined;
  isIntersecting: boolean;
};

export function useIntersectionObserver(
  options: UseIntersectionObserverOptions = {}
): UseIntersectionObserverReturn {
  const {
    threshold = 0,
    root = null,
    rootMargin = '0px',
    freezeOnceVisible = false,
    onChange,
    enabled = true,
  } = options;

  const [entry, setEntry] = React.useState<IntersectionObserverEntry>();
  const previousObserver = React.useRef<IntersectionObserver | null>(null);
  const frozen = entry?.isIntersecting && freezeOnceVisible;

  const ref = React.useCallback(
    (node: Element | null) => {
      if (previousObserver.current) {
        previousObserver.current.disconnect();
        previousObserver.current = null;
      }

      if (frozen || !enabled) return;

      if (node?.nodeType === Node.ELEMENT_NODE) {
        const observer = new IntersectionObserver(
          ([newEntry]) => {
            setEntry(newEntry);
            if (newEntry) onChange?.(newEntry);
          },
          { threshold, root, rootMargin }
        );

        observer.observe(node);
        previousObserver.current = observer;
      }
    },
    [threshold, root, rootMargin, frozen, enabled, onChange]
  );

  return { ref, entry, isIntersecting: entry?.isIntersecting ?? false };
}

import * as React from 'react';

const MOBILE_BREAKPOINT = 768;

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined);

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`);
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    };
    mql.addEventListener('change', onChange);
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    return () => mql.removeEventListener('change', onChange);
  }, []);

  return !!isMobile;
}

'use client';

import { useEffect, useState } from 'react';

/**
 * Hook to detect user's motion preference
 * @returns true if user prefers reduced motion, false otherwise
 */
export function useReducedMotion(): boolean {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);

  useEffect(() => {
    // Create media query for prefers-reduced-motion
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');

    // Set initial value
    setPrefersReducedMotion(mediaQuery.matches);

    // Create listener for changes
    const handleChange = (event: MediaQueryListEvent) => {
      setPrefersReducedMotion(event.matches);
    };

    // Add event listener
    mediaQuery.addEventListener('change', handleChange);

    // Cleanup on unmount
    return () => {
      mediaQuery.removeEventListener('change', handleChange);
    };
  }, []);

  return prefersReducedMotion;
}

import type {
  ColumnFiltersState,
  OnChangeFn,
  PaginationState,
  SortingState,
} from '@tanstack/react-table';
import { useMemo, useRef, useState } from 'react';

type SearchRecord = Record<string, unknown>;

type UseTableLocalStateParams = {
  pagination?: {
    pageKey?: string;
    pageSizeKey?: string;
    defaultPage?: number;
    defaultPageSize?: number;
  };
  globalFilter?: {
    enabled?: boolean;
    key?: string;
    trim?: boolean;
    debounceMs?: number; // Debounce delay in milliseconds (default: 300)
  };
  columnFilters?: Array<
    | {
        columnId: string;
        searchKey: string;
        type?: 'string';
        // Optional transformers for custom types
        serialize?: (value: unknown) => unknown;
        deserialize?: (value: unknown) => unknown;
      }
    | {
        columnId: string;
        searchKey: string;
        type: 'array';
        serialize?: (value: unknown) => unknown;
        deserialize?: (value: unknown) => unknown;
      }
  >;
};

export type UseTableLocalStateReturn<TParams = SearchRecord> = {
  // Global filter
  globalFilter?: string;
  onGlobalFilterChange?: OnChangeFn<string>;
  // Column filters
  columnFilters: ColumnFiltersState;
  onColumnFiltersChange: OnChangeFn<ColumnFiltersState>;
  // Pagination
  pagination: PaginationState;
  onPaginationChange: OnChangeFn<PaginationState>;
  // Sorting (client-side — satisfies DataTable urlState interface)
  sorting: SortingState;
  onSortingChange: OnChangeFn<SortingState>;
  // Params (similar to URL search params)
  params: TParams;
  // Helpers
  ensurePageInRange: (pageCount: number, opts?: { resetTo?: 'first' | 'last' }) => void;
  resetFilters: () => void;
  setParams: (nextParams: SearchRecord) => void;
};

export function useTableLocalState<TParams extends SearchRecord = SearchRecord>(
  params: UseTableLocalStateParams = {}
): UseTableLocalStateReturn<TParams> {
  const {
    pagination: paginationCfg,
    globalFilter: globalFilterCfg,
    columnFilters: columnFiltersCfg = [],
  } = params;

  const pageKey = paginationCfg?.pageKey ?? ('offset' as string);
  const pageSizeKey = paginationCfg?.pageSizeKey ?? ('limit' as string);
  const defaultPage = paginationCfg?.defaultPage ?? 1;
  const defaultPageSize = paginationCfg?.defaultPageSize ?? 20;
  const isOffsetBased = pageKey === 'offset';

  const globalFilterKey = globalFilterCfg?.key ?? ('filter' as string);
  const globalFilterEnabled = globalFilterCfg?.enabled ?? true;
  const trimGlobal = globalFilterCfg?.trim ?? true;
  const debounceMs = globalFilterCfg?.debounceMs ?? 300;

  // State management
  const [internalState, setInternalState] = useState<SearchRecord>(() => {
    const initial: SearchRecord = {};
    // Initialize with default pagination values if offset-based
    if (isOffsetBased) {
      initial[pageKey] = 0;
      initial[pageSizeKey] = defaultPageSize;
    } else {
      initial[pageKey] = defaultPage;
      initial[pageSizeKey] = defaultPageSize;
    }
    return initial;
  });

  // Build column filters from internal state
  const columnFilters: ColumnFiltersState = useMemo(() => {
    const collected: ColumnFiltersState = [];
    for (const cfg of columnFiltersCfg) {
      const raw = internalState[cfg.searchKey];
      const deserialize = cfg.deserialize ?? ((v: unknown) => v);
      if (cfg.type === 'string') {
        const value = (deserialize(raw) as string) ?? '';
        if (typeof value === 'string' && value.trim() !== '') {
          collected.push({ id: cfg.columnId, value });
        }
      } else {
        // default to array type
        const value = (deserialize(raw) as unknown[]) ?? [];
        if (Array.isArray(value) && value.length > 0) {
          collected.push({ id: cfg.columnId, value });
        }
      }
    }
    return collected;
  }, [columnFiltersCfg, internalState]);

  // Build pagination from internal state
  const pagination: PaginationState = useMemo(() => {
    const rawPageSize = internalState[pageSizeKey];
    const pageSizeNum = typeof rawPageSize === 'number' ? rawPageSize : defaultPageSize;

    if (isOffsetBased) {
      // For offset-based pagination: offset = pageIndex * pageSize
      const rawOffset = internalState[pageKey];
      const offset = typeof rawOffset === 'number' ? rawOffset : 0;
      const pageIndex = Math.floor(offset / pageSizeNum);
      return { pageIndex: Math.max(0, pageIndex), pageSize: pageSizeNum };
    }

    // For page-based pagination (default)
    const rawPage = internalState[pageKey];
    const pageNum = typeof rawPage === 'number' ? rawPage : defaultPage;
    return { pageIndex: Math.max(0, pageNum - 1), pageSize: pageSizeNum };
  }, [internalState, pageKey, pageSizeKey, defaultPage, defaultPageSize, isOffsetBased]);

  const onPaginationChange: OnChangeFn<PaginationState> = (updater) => {
    const next = typeof updater === 'function' ? updater(pagination) : updater;
    const nextPageSize = next.pageSize;

    setInternalState((prev) => {
      const updated = { ...prev };

      if (isOffsetBased) {
        // For offset-based pagination: calculate offset from pageIndex
        const nextOffset = next.pageIndex * nextPageSize;
        updated[pageKey] = nextOffset === 0 ? undefined : nextOffset;
        updated[pageSizeKey] = nextPageSize === defaultPageSize ? undefined : nextPageSize;
      } else {
        // For page-based pagination (default)
        const nextPage = next.pageIndex + 1;
        updated[pageKey] = nextPage <= defaultPage ? undefined : nextPage;
        updated[pageSizeKey] = nextPageSize === defaultPageSize ? undefined : nextPageSize;
      }

      return updated;
    });
  };

  const [sorting, setSorting] = useState<SortingState>([]);

  const [globalFilter, setGlobalFilter] = useState<string>(() => {
    if (!globalFilterEnabled) return '';
    const raw = internalState[globalFilterKey];
    return typeof raw === 'string' ? raw : '';
  });

  const [debouncedGlobalFilter, setDebouncedGlobalFilter] = useState<string>(globalFilter);

  // Debounced value for filter updates
  const debounceTimerRef = useRef<NodeJS.Timeout | undefined>(undefined);

  const onGlobalFilterChange: OnChangeFn<string> | undefined = globalFilterEnabled
    ? (updater) => {
        const next = typeof updater === 'function' ? updater(globalFilter ?? '') : updater;
        const value = trimGlobal ? next.trim() : next;

        // Update local state immediately for responsive UI
        setGlobalFilter(value);

        // Debounce internal state update
        if (debounceTimerRef.current) {
          clearTimeout(debounceTimerRef.current);
        }

        debounceTimerRef.current = setTimeout(() => {
          setDebouncedGlobalFilter(value);
          setInternalState((prev) => ({
            ...prev,
            [pageKey]: undefined,
            [globalFilterKey]: value ? value : undefined,
          }));
        }, debounceMs);
      }
    : undefined;

  const onColumnFiltersChange: OnChangeFn<ColumnFiltersState> = (updater) => {
    const next = typeof updater === 'function' ? updater(columnFilters) : updater;

    const patch: SearchRecord = {};

    for (const cfg of columnFiltersCfg) {
      const found = next.find((f) => f.id === cfg.columnId);
      const serialize = cfg.serialize ?? ((v: unknown) => v);
      if (cfg.type === 'string') {
        const value = typeof found?.value === 'string' ? (found.value as string) : '';
        patch[cfg.searchKey] = value.trim() !== '' ? serialize(value) : undefined;
      } else {
        const value = Array.isArray(found?.value) ? (found?.value as unknown[]) : [];
        patch[cfg.searchKey] = value.length > 0 ? serialize(value) : undefined;
      }
    }

    setInternalState((prev) => ({
      ...prev,
      [pageKey]: undefined,
      ...patch,
    }));
  };

  const ensurePageInRange = (
    pageCount: number,
    opts: { resetTo?: 'first' | 'last' } = { resetTo: 'first' }
  ) => {
    const currentPage = internalState[pageKey];
    const pageNum = typeof currentPage === 'number' ? currentPage : defaultPage;
    if (pageCount > 0 && pageNum > pageCount) {
      setInternalState((prev) => ({
        ...prev,
        [pageKey]: opts.resetTo === 'last' ? pageCount : undefined,
      }));
    }
  };

  const resetFilters = () => {
    const initial: SearchRecord = {};
    // Reset to default pagination values
    if (isOffsetBased) {
      initial[pageKey] = 0;
      initial[pageSizeKey] = defaultPageSize;
    } else {
      initial[pageKey] = defaultPage;
      initial[pageSizeKey] = defaultPageSize;
    }
    setInternalState(initial);
    setGlobalFilter('');
    setDebouncedGlobalFilter('');
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
    }
  };

  // Build params object for API calls (similar to URL search params)
  const paramsObj = useMemo(() => {
    const result: SearchRecord = { ...internalState };

    // Clean up undefined values
    for (const key in result) {
      if (result[key] === undefined) {
        delete result[key];
      }
    }

    return result as unknown as TParams;
  }, [internalState]);

  const setParams = (nextParams: SearchRecord) => {
    setInternalState((prev) => ({
      ...nextParams,
      [pageKey]: nextParams[pageKey] ?? (isOffsetBased ? 0 : 1),
      [pageSizeKey]:
        nextParams[pageSizeKey] ??
        prev[pageSizeKey] ??
        (isOffsetBased ? defaultPageSize : undefined),
    }));
  };

  return {
    globalFilter: globalFilterEnabled ? debouncedGlobalFilter : undefined,
    onGlobalFilterChange,
    columnFilters,
    onColumnFiltersChange,
    pagination,
    onPaginationChange,
    sorting,
    onSortingChange: setSorting,
    params: paramsObj,
    ensurePageInRange,
    resetFilters,
    setParams,
  };
}

import type {
  ColumnFiltersState,
  OnChangeFn,
  PaginationState,
  SortingState,
} from '@tanstack/react-table';
import { useEffect, useMemo, useRef, useState } from 'react';

type SearchRecord = Record<string, unknown>;

export type NavigateFn = (opts: {
  search: true | SearchRecord | ((prev: SearchRecord) => Partial<SearchRecord> | SearchRecord);
  replace?: boolean;
}) => void;

type UseTableUrlStateParams = {
  search: SearchRecord;
  navigate: NavigateFn;
  pagination?: {
    pageKey?: string;
    pageSizeKey?: string;
    defaultPage?: number;
    defaultPageSize?: number;
  };
  globalFilter?: {
    enabled?: boolean;
    key?: string;
    trim?: boolean;
    debounceMs?: number; // Debounce delay in milliseconds (default: 300)
  };
  columnFilters?: Array<
    | {
        columnId: string;
        searchKey: string;
        type?: 'string';
        // Optional transformers for custom types
        serialize?: (value: unknown) => unknown;
        deserialize?: (value: unknown) => unknown;
      }
    | {
        columnId: string;
        searchKey: string;
        type: 'array';
        serialize?: (value: unknown) => unknown;
        deserialize?: (value: unknown) => unknown;
      }
  >;
  sorting?: {
    /** URL key for the column id to sort by. @default 'order_by' */
    orderByKey?: string;
    /** URL key for the sort direction. @default 'descending' */
    descendingKey?: string;
  };
};

export type UseTableUrlStateReturn = {
  // Global filter
  globalFilter?: string;
  onGlobalFilterChange?: OnChangeFn<string>;
  // Column filters
  columnFilters: ColumnFiltersState;
  onColumnFiltersChange: OnChangeFn<ColumnFiltersState>;
  // Pagination
  pagination: PaginationState;
  onPaginationChange: OnChangeFn<PaginationState>;
  // Sorting
  sorting: SortingState;
  onSortingChange: OnChangeFn<SortingState>;
  // Helpers
  ensurePageInRange: (pageCount: number, opts?: { resetTo?: 'first' | 'last' }) => void;
};

export function useTableUrlState(params: UseTableUrlStateParams): UseTableUrlStateReturn {
  const {
    search,
    navigate,
    pagination: paginationCfg,
    globalFilter: globalFilterCfg,
    columnFilters: columnFiltersCfg = [],
    sorting: sortingCfg,
  } = params;

  const pageKey = paginationCfg?.pageKey ?? ('offset' as string);
  const pageSizeKey = paginationCfg?.pageSizeKey ?? ('limit' as string);
  const defaultPage = paginationCfg?.defaultPage ?? 1;
  const defaultPageSize = paginationCfg?.defaultPageSize ?? 20;
  const isOffsetBased = pageKey === 'offset';

  const globalFilterKey = globalFilterCfg?.key ?? ('filter' as string);
  const globalFilterEnabled = globalFilterCfg?.enabled ?? true;
  const trimGlobal = globalFilterCfg?.trim ?? true;
  const debounceMs = globalFilterCfg?.debounceMs ?? 300;

  // Build initial column filters from the current search params
  const initialColumnFilters: ColumnFiltersState = useMemo(() => {
    const collected: ColumnFiltersState = [];
    for (const cfg of columnFiltersCfg) {
      const raw = (search as SearchRecord)[cfg.searchKey];
      const deserialize = cfg.deserialize ?? ((v: unknown) => v);
      if (cfg.type === 'string') {
        const value = (deserialize(raw) as string) ?? '';
        if (typeof value === 'string' && value.trim() !== '') {
          collected.push({ id: cfg.columnId, value });
        }
      } else {
        // default to array type
        const value = (deserialize(raw) as unknown[]) ?? [];
        if (Array.isArray(value) && value.length > 0) {
          collected.push({ id: cfg.columnId, value });
        }
      }
    }
    return collected;
  }, [columnFiltersCfg, search]);

  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>(initialColumnFilters);

  const pagination: PaginationState = useMemo(() => {
    const rawPageSize = (search as SearchRecord)[pageSizeKey];
    const pageSizeNum = typeof rawPageSize === 'number' ? rawPageSize : defaultPageSize;

    if (isOffsetBased) {
      // For offset-based pagination: offset = pageIndex * pageSize
      const rawOffset = (search as SearchRecord)[pageKey];
      const offset = typeof rawOffset === 'number' ? rawOffset : 0;
      const pageIndex = Math.floor(offset / pageSizeNum);
      return { pageIndex: Math.max(0, pageIndex), pageSize: pageSizeNum };
    }

    // For page-based pagination (default)
    const rawPage = (search as SearchRecord)[pageKey];
    const pageNum = typeof rawPage === 'number' ? rawPage : defaultPage;
    return { pageIndex: Math.max(0, pageNum - 1), pageSize: pageSizeNum };
  }, [search, pageKey, pageSizeKey, defaultPage, defaultPageSize, isOffsetBased]);

  const onPaginationChange: OnChangeFn<PaginationState> = (updater) => {
    const next = typeof updater === 'function' ? updater(pagination) : updater;
    const nextPageSize = next.pageSize;

    if (isOffsetBased) {
      // For offset-based pagination: calculate offset from pageIndex
      const nextOffset = next.pageIndex * nextPageSize;
      navigate({
        search: (prev) => ({
          ...(prev as SearchRecord),
          [pageKey]: nextOffset === 0 ? undefined : nextOffset,
          [pageSizeKey]: nextPageSize === defaultPageSize ? undefined : nextPageSize,
        }),
      });
    } else {
      // For page-based pagination (default)
      const nextPage = next.pageIndex + 1;
      navigate({
        search: (prev) => ({
          ...(prev as SearchRecord),
          [pageKey]: nextPage <= defaultPage ? undefined : nextPage,
          [pageSizeKey]: nextPageSize === defaultPageSize ? undefined : nextPageSize,
        }),
      });
    }
  };

  const [globalFilter, setGlobalFilter] = useState<string | undefined>(() => {
    if (!globalFilterEnabled) return undefined;
    const raw = (search as SearchRecord)[globalFilterKey];
    return typeof raw === 'string' ? raw : '';
  });

  // Debounced value for URL updates
  const debounceTimerRef = useRef<NodeJS.Timeout | undefined>(undefined);

  // Sync URL to local state when URL changes externally (e.g., browser back/forward)
  useEffect(() => {
    if (!globalFilterEnabled) return;
    const raw = (search as SearchRecord)[globalFilterKey];
    const urlValue = typeof raw === 'string' ? raw : '';
    if (urlValue !== globalFilter) {
      setGlobalFilter(urlValue);
    }
  }, [search, globalFilterKey, globalFilterEnabled]);

  const onGlobalFilterChange: OnChangeFn<string> | undefined = globalFilterEnabled
    ? (updater) => {
        const next = typeof updater === 'function' ? updater(globalFilter ?? '') : updater;
        const value = trimGlobal ? next.trim() : next;

        // Update local state immediately for responsive UI
        setGlobalFilter(value);

        // Debounce URL update
        if (debounceTimerRef.current) {
          clearTimeout(debounceTimerRef.current);
        }

        debounceTimerRef.current = setTimeout(() => {
          navigate({
            search: (prev) => ({
              ...(prev as SearchRecord),
              [pageKey]: undefined,
              [globalFilterKey]: value ? value : undefined,
            }),
          });
        }, debounceMs);
      }
    : undefined;

  const onColumnFiltersChange: OnChangeFn<ColumnFiltersState> = (updater) => {
    const next = typeof updater === 'function' ? updater(columnFilters) : updater;
    setColumnFilters(next);

    const patch: Record<string, unknown> = {};

    for (const cfg of columnFiltersCfg) {
      const found = next.find((f) => f.id === cfg.columnId);
      const serialize = cfg.serialize ?? ((v: unknown) => v);
      if (cfg.type === 'string') {
        const value = typeof found?.value === 'string' ? (found.value as string) : '';
        patch[cfg.searchKey] = value.trim() !== '' ? serialize(value) : undefined;
      } else {
        const value = Array.isArray(found?.value) ? (found?.value as unknown[]) : [];
        patch[cfg.searchKey] = value.length > 0 ? serialize(value) : undefined;
      }
    }

    navigate({
      search: (prev) => ({
        ...(prev as SearchRecord),
        [pageKey]: undefined,
        ...patch,
      }),
    });
  };

  const orderByKey = sortingCfg?.orderByKey ?? 'order_by';
  const descendingKey = sortingCfg?.descendingKey ?? 'descending';

  const sorting: SortingState = useMemo(() => {
    const rawOrderBy = (search as SearchRecord)[orderByKey];
    const rawDescending = (search as SearchRecord)[descendingKey];
    if (!rawOrderBy) return [];
    const col = Array.isArray(rawOrderBy) ? rawOrderBy[0] : rawOrderBy;
    const desc = Array.isArray(rawDescending) ? rawDescending[0] : rawDescending;
    return [{ id: String(col), desc: desc === true || desc === 'true' }];
  }, [search, orderByKey, descendingKey]);

  const onSortingChange: OnChangeFn<SortingState> = (updater) => {
    const next = typeof updater === 'function' ? updater(sorting) : updater;
    const sortConfig = next?.[0];
    navigate({
      search: (prev) => ({
        ...(prev as SearchRecord),
        [orderByKey]: sortConfig?.id ?? undefined,
        [descendingKey]: sortConfig ? sortConfig.desc : undefined,
        [pageKey]: undefined,
      }),
    });
  };

  const ensurePageInRange = (
    pageCount: number,
    opts: { resetTo?: 'first' | 'last' } = { resetTo: 'first' }
  ) => {
    const currentPage = (search as SearchRecord)[pageKey];
    const pageNum = typeof currentPage === 'number' ? currentPage : defaultPage;
    if (pageCount > 0 && pageNum > pageCount) {
      navigate({
        replace: true,
        search: (prev) => ({
          ...(prev as SearchRecord),
          [pageKey]: opts.resetTo === 'last' ? pageCount : undefined,
        }),
      });
    }
  };

  return {
    globalFilter: globalFilterEnabled ? (globalFilter ?? '') : undefined,
    onGlobalFilterChange,
    columnFilters,
    onColumnFiltersChange,
    pagination,
    onPaginationChange,
    sorting,
    onSortingChange,
    ensurePageInRange,
  };
}

import type { Control, FieldValues } from 'react-hook-form';
import { useWatch } from 'react-hook-form';

type UseWatchedFieldOptions = {
  watchName?: string[];
  control: Control<FieldValues>;
  enabled?: boolean;
};

type UseWatchedFieldReturn = {
  watchedValues: unknown[];
  queryParams: Record<string, string>;
};

/**
 * A hook that watches form fields and triggers a callback when values change.
 * Uses ref-based tracking to detect changes during render, avoiding useEffect.
 *
 * @param options - Configuration options
 * @param options.watchName - Array of field names to watch
 * @param options.control - The react-hook-form control instance
 * @param options.enabled - Whether the watch is enabled (default: true)
 * @returns Object containing watched values and computed query params
 */
export function useWatchField({
  watchName,
  control,
  enabled = true,
}: UseWatchedFieldOptions): UseWatchedFieldReturn {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const watchedValues = useWatch({
    control,
    name: (watchName ?? []) as any,
    disabled: !watchName?.length || !enabled,
  });

  // Compute query params from watched values
  const queryParams = watchName
    ? (watchedValues as unknown[]).reduce<Record<string, string>>((acc, value, index) => {
        if (value) {
          acc[watchName[index] ?? ''] =
            typeof value === 'string' ? value : (value as string[]).join(',');
        }
        return acc;
      }, {})
    : {};

  return {
    watchedValues: watchedValues as unknown[],
    queryParams,
  };
}
